import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd(); fz = repo / 'target/debug/fz'

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def compile_profile(name, source, strict=False):
    root = write_project(name, source)
    cmd = [str(fz), 'build', str(root), '--json']
    if strict:
        cmd.append('--strict')
    proc = subprocess.run(cmd, cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    return root, proc.returncode, payload

def verify_project(name, source, strict=False):
    root = write_project(name, source)
    cmd = [str(fz), 'verify', str(root), '--json']
    if strict:
        cmd.append('--strict')
    proc = subprocess.run(cmd, cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    return root, proc.returncode, payload

def find(items, needle):
    return next(item for item in items if needle in item['message'])

root_join, rc_join, payload_join = compile_profile('task_join_state', '''
    use core.thread;
    fn worker() -> i32 {
        return 7
    }
    fn main() -> i32 {
        let handle = spawn(worker)
        let status = task_result(handle)
        if status < 0 {
            return join(handle)
        }
        return join(handle)
    }
''')
assert rc_join == 0 and payload_join['status'] == 'ok', (rc_join, payload_join)
async_join = json.loads((root_join / '.fz' / 'async-safety.json').read_text())
handle_join = next(item for item in async_join['task_handle_policies'] if item['handle'] == 'handle')
assert handle_join['currentState'] == 'joined', handle_join
assert handle_join['resultReadsBeforeTerminal'] == 1, handle_join
assert handle_join['resultReadsAfterTerminal'] == 0, handle_join

root_detach, rc_detach, payload_detach = compile_profile('task_detach_result_after', '''
    use core.thread;
    fn worker() -> i32 {
        return 7
    }
    fn main() -> i32 {
        let handle = spawn(worker)
        detach(handle)
        discard task_result(handle)
        cancel_task(handle)
        return 0
    }
''')
assert payload_detach['status'] == 'error', payload_detach
async_detach = json.loads((root_detach / '.fz' / 'async-safety.json').read_text())
handle_detach = next(item for item in async_detach['task_handle_policies'] if item['handle'] == 'handle')
assert handle_detach['currentState'] == 'invalid_result_after_terminal', handle_detach
assert handle_detach['resultReadsAfterTerminal'] == 1, handle_detach
assert any(item['kind'] == 'task_handle_double_terminal' for item in async_detach['task_handle_findings']), async_detach
assert any(item['kind'] == 'task_result_after_terminal' for item in async_detach['task_handle_findings']), async_detach

root_leak, rc_leak, payload_leak = verify_project('task_missing_terminal', '''
    use core.thread;
    fn worker() -> i32 {
        return 7
    }
    fn main() -> i32 {
        let handle = spawn(worker)
        discard 0
        return 0
    }
''', strict=True)
assert rc_leak == 1, (rc_leak, payload_leak)
leak_diag = find(payload_leak['items'], 'task handle `handle` is created by `spawn` and exits `main` without `join`, `detach`, or `cancel_task`')
assert 'Terminate every task handle exactly once' in (leak_diag.get('help') or ''), leak_diag
async_leak = json.loads((root_leak / '.fz' / 'async-safety.json').read_text())
handle_leak = next(item for item in async_leak['task_handle_policies'] if item['handle'] == 'handle')
assert handle_leak['currentState'] == 'missing_terminal', handle_leak

root_group, rc_group, payload_group = verify_project('group_missing_terminal', '''
    use core.thread;
    fn worker() -> i32 {
        return 7
    }
    fn main() -> i32 {
        let group = task.group_begin()
        discard task.group_spawn(group, worker)
        return 0
    }
''', strict=True)
assert rc_group == 1, (rc_group, payload_group)
group_diag = find(payload_group['items'], 'task group `group` is created by `task.group_begin()` and exits `main` without `task.group_join`, `task.group_join_all`, or `task.group_cancel`')
assert 'Terminate every task group explicitly' in (group_diag.get('help') or ''), group_diag
async_group = json.loads((root_group / '.fz' / 'async-safety.json').read_text())
group_state = next(item for item in async_group['task_group_policies'] if item['group'] == 'group')
assert group_state['currentState'] == 'missing_terminal', group_state

root_wrapper, rc_wrapper, payload_wrapper = compile_profile('task_wrapper_terminal', '''
    use core.thread;
    fn worker() -> i32 {
        return 7
    }
    fn finish(handle: TaskHandle) -> i32 {
        return join(handle)
    }
    fn main() -> i32 {
        let handle = spawn(worker)
        return finish(handle)
    }
''')
assert rc_wrapper == 0 and payload_wrapper['status'] == 'ok', (rc_wrapper, payload_wrapper)
async_wrapper = json.loads((root_wrapper / '.fz' / 'async-safety.json').read_text())
handle_wrapper = next(item for item in async_wrapper['task_handle_policies'] if item['handle'] == 'handle')
assert handle_wrapper['policy'] == 'join via finish', handle_wrapper
assert handle_wrapper['currentState'] == 'joined', handle_wrapper
print('compiler-async-task-state-machine-ok')

